#include <stdio.h>
void select_min(int **selected, int *bins, int count) {
    int *best = bins;
    for (int i = 1; i < count; i++) {
        if (bins[i] < *best) best = &bins[i];
    }
    // 호출자가 가진 포인터를 최소 재고 칸으로 옮기세요.
    **selected = *best;
}
int main(void) {
    int bins[] = {8, 2, 5};
    int count = 3;
    int *chosen = &bins[0];
    select_min(&chosen, bins, count);
    printf("%d %d %d", (int)(chosen - bins), *chosen, bins[0]);
    return 0;
}

